FoamFile
{
    format      ascii;
    class       dictionary;
    object      controlDict;
}

application     buoyantFoam;

startFrom       startTime;
startTime       0;
stopAt          endTime;
endTime         1000;
deltaT          1;

writeControl    timeStep;
writeInterval   50;
purgeWrite      0;
writeFormat     ascii;
writePrecision  10;
writeCompression off;
timeFormat      general;
timePrecision   10;

runTimeModifiable false;

functions
{
}

FoamFile
{
    format      ascii;
    class       dictionary;
    object      fvSchemes;
}

ddtSchemes
{
    default         steadyState;
}

gradSchemes
{
    default         Gauss linear;
    grad(U)         cellLimited Gauss linear 1;
    grad(h)         cellLimited Gauss linear 1;
    grad(k)         cellLimited Gauss linear 1;
    grad(omega)     cellLimited Gauss linear 1;
}

divSchemes
{
    default                                             none;
    div(phi,U)                                          bounded Gauss upwind;
    div(phi,h)                                          bounded Gauss upwind;
    div(phi,K)                                          Gauss linear;
    div(phi,k)                                          bounded Gauss upwind;
    div(phi,omega)                                      bounded Gauss upwind;
    div(((rho*nuEff)*dev2(T(grad(U)))))                 Gauss linear;
}

laplacianSchemes
{
    default         Gauss linear corrected;
}

interpolationSchemes
{
    default         linear;
}

snGradSchemes
{
    default         corrected;
}

wallDist
{
    method          meshWave;
}

FoamFile
{
    format      ascii;
    class       dictionary;
    object      fvSolution;
}

solvers
{
    p_rgh
    {
        solver          GAMG;
        tolerance       1e-9;
        relTol          0.03;
        smoother        DICGaussSeidel;
        cacheAgglomeration true;
        agglomerator    faceAreaPair;
        nCellsInCoarsestLevel 20;
        mergeLevels     1;
    }

    p_rghFinal
    {
        $p_rgh;
        tolerance       1e-10;
        relTol          0;
    }

    U
    {
        solver          smoothSolver;
        smoother        symGaussSeidel;
        tolerance       1e-9;
        relTol          0.05;
        nSweeps         1;
    }

    UFinal
    {
        $U;
        tolerance       1e-10;
        relTol          0;
    }

    h
    {
        solver          smoothSolver;
        smoother        symGaussSeidel;
        tolerance       1e-9;
        relTol          0.03;
        nSweeps         1;
    }

    hFinal
    {
        $h;
        tolerance       1e-10;
        relTol          0;
    }

    k
    {
        solver          smoothSolver;
        smoother        symGaussSeidel;
        tolerance       1e-9;
        relTol          0.05;
        nSweeps         1;
    }

    kFinal
    {
        $k;
        tolerance       1e-10;
        relTol          0;
    }

    omega
    {
        solver          smoothSolver;
        smoother        symGaussSeidel;
        tolerance       1e-9;
        relTol          0.05;
        nSweeps         1;
    }

    omegaFinal
    {
        $omega;
        tolerance       1e-10;
        relTol          0;
    }

    rho
    {
        solver          diagonal;
    }
}

PIMPLE
{
    momentumPredictor       yes;
    nOuterCorrectors        1;
    nCorrectors             2;
    nNonOrthogonalCorrectors 0;

    pRefCell                0;
    pRefValue               100000;

    residualControl
    {
        p_rgh               1e-30;
        U                   1e-30;
        h                   1e-30;
        k                   1e-30;
        omega               1e-30;
    }
}

relaxationFactors
{
    fields
    {
        p_rgh           0.3;
        rho             0.7;
    }

    equations
    {
        U               0.45;
        h               0.65;
        k               0.5;
        omega           0.5;
    }
}

